import {seeded,insideLake} from './model.js';
import {LAKE,LANDMARKS,terrainHeight} from './world.js';
import {makeStoneMaterial} from './materials.js';

export function makeScenery(THREE,scene,padSpots=[]){
 const random=seeded(61129),range=(a,b)=>a+random()*(b-a),dummy=new THREE.Object3D(),groups=new Map(),occluders=[];
 const sphere=new THREE.SphereGeometry(1,8,6),cylinder=new THREE.CylinderGeometry(.8,1,1,8),cap=new THREE.SphereGeometry(1,12,8,0,Math.PI*2,0,Math.PI/2);
 const leaf=new THREE.BufferGeometry();leaf.setAttribute('position',new THREE.Float32BufferAttribute([0,0,0,-.5,0,.5,0,.06,1,.5,0,.5],3));leaf.setIndex([0,1,2,0,2,3]);leaf.computeVertexNormals();
 const palettes={leaf:new THREE.MeshStandardMaterial({color:0xffffff,roughness:.85,side:THREE.DoubleSide}),soil:new THREE.MeshStandardMaterial({color:0xffffff,roughness:1}),stone:makeStoneMaterial(THREE)};
 function add(kind,geo,mat,pos,scale,color,rotation=[0,0,0]){if(!groups.has(kind))groups.set(kind,{geo,mat,items:[]});dummy.position.set(...pos);dummy.scale.set(...scale);dummy.rotation.set(...rotation);dummy.updateMatrix();groups.get(kind).items.push({matrix:dummy.matrix.clone(),color});}
 // Small fern fronds have separate tapered leaflets, not a single solid crown.
 for(let i=0;i<180;i++){const angle=range(0,6.28),r=range(1.25,3.4),x=Math.cos(angle)*LAKE.x*r,z=Math.sin(angle)*LAKE.z*r,y=terrainHeight(x,z);for(let f=0;f<6;f++){const a=f*Math.PI/3+range(-.2,.2);for(let k=1;k<7;k++){const t=k/7,rx=x+Math.sin(a)*t*.9,rz=z+Math.cos(a)*t*.9,ry=y+Math.sin(t*Math.PI*.8)*.5;for(const side of [-1,1])add('fern',leaf,'leaf',[rx,ry,rz],[.16*(1-t)+.04,1,.29*(1-t)+.08],f%2?0x459c51:0x91be42,[.2,a+side*.8,0]);}}}
 for(let i=0;i<130;i++){const a=range(0,6.28),r=range(1.5,4),x=Math.cos(a)*LAKE.x*r,z=Math.sin(a)*LAKE.z*r,y=terrainHeight(x,z),h=range(.15,.34);add('mushroom-stem',cylinder,'soil',[x,y+h/2,z],[.035,h,.035],0xe9d7ad);add('mushroom-cap',cap,'soil',[x,y+h,z],[h*.7,h*.35,h*.7],i%3===0?0xc16c3f:0xdf925b);}
 for(let i=0;i<260;i++){const a=range(0,6.28),r=range(1.03,1.09),x=Math.cos(a)*LAKE.x*r,z=Math.sin(a)*LAKE.z*r,y=terrainHeight(x,z),h=range(.6,1.3);add('reed',cylinder,'leaf',[x,y+h/2,z],[.015,h,.015],0x57864b,[range(-.12,.12),0,range(-.12,.12)]);if(i%3===0)add('reed-head',sphere,'soil',[x,y+h,z],[.045,.17,.045],0x865c38);}
 for(let i=0;i<padSpots.length;i+=5){const p=padSpots[i];for(let j=0;j<7;j++){const a=j*Math.PI*2/7;add('lily-petal',sphere,'leaf',[p.x+Math.cos(a)*.12,.18,p.z+Math.sin(a)*.12],[.15,.045,.075],i%2?0xffb9d9:0xffe8c0,[0,-a,0]);}add('lily-heart',sphere,'leaf',[p.x,.22,p.z],[.075,.04,.075],0xffcd45);}
 // Fallen wood has visible light end-grain rings and moss along the upper side.
 for(let i=0;i<22;i++){const a=range(0,6.28),r=range(1.7,4.5),x=Math.cos(a)*LAKE.x*r,z=Math.sin(a)*LAKE.z*r,y=terrainHeight(x,z),length=range(2.2,4.5),radius=range(.16,.3),root=new THREE.Group();root.position.set(x,y+radius*.7,z);root.rotation.y=range(0,6.28);scene.add(root);const wood=new THREE.Mesh(new THREE.CylinderGeometry(radius*.85,radius,length,10),new THREE.MeshStandardMaterial({color:0x73503a,roughness:1}));wood.rotation.z=Math.PI/2;root.add(wood);occluders.push(wood);for(const side of [-1,1]){const end=new THREE.Mesh(new THREE.CircleGeometry(radius*.86,24),new THREE.MeshStandardMaterial({color:0xcbb280,roughness:1,side:THREE.DoubleSide}));end.rotation.y=Math.PI/2;end.position.x=side*(length/2+.005);root.add(end);for(const fraction of [.35,.65]){const ring=new THREE.Mesh(new THREE.TorusGeometry(radius*fraction,.007,4,24),new THREE.MeshStandardMaterial({color:0x886d43}));ring.rotation.y=Math.PI/2;ring.position.x=side*(length/2+.01);root.add(ring);}}add('log-moss',sphere,'leaf',[x,y+radius*1.5,z],[.45,.08,.24],0x649333);}
 // Distinct destinations give the expanded ground something to discover.
 for(let k=0;k<LANDMARKS.length;k++){const place=LANDMARKS[k];if(k===0){for(let i=0;i<1300;i++){const a=range(0,6.28),r=Math.sqrt(random())*24,x=place.x+Math.cos(a)*r,z=place.z+Math.sin(a)*r;if(insideLake(x,z,1.1))continue;const y=terrainHeight(x,z)+range(.2,.55);add('meadow-flower',sphere,'leaf',[x,y,z],[.16,.08,.16],[0xffcc42,0xff7891,0xaf86ec,0x7cc8f4,0xffefd0][i%5]);}}else for(let i=0;i<18;i++){const a=range(0,6.28),r=range(2,14),x=place.x+Math.cos(a)*r,z=place.z+Math.sin(a)*r;add('boulder',sphere,'stone',[x,terrainHeight(x,z)+.35,z],[range(1,2.7),range(.8,2.2),range(.9,2)],0xa8b0a1,[.1,a,.2]);}}
 const detail=[];for(const [kind,batch]of groups){const mesh=new THREE.InstancedMesh(batch.geo,palettes[batch.mat],batch.items.length);batch.items.forEach((item,i)=>{mesh.setMatrixAt(i,item.matrix);mesh.setColorAt(i,new THREE.Color(item.color));});mesh.computeBoundingSphere();mesh.receiveShadow=true;scene.add(mesh);detail.push({mesh,range:kind==='boulder'?500:180});if(kind==='boulder')occluders.push(mesh);}
 const butterflies=[];for(let i=0;i<18;i++){const root=new THREE.Group(),a=range(0,6.28),r=range(1.2,2.7),x=Math.cos(a)*LAKE.x*r,z=Math.sin(a)*LAKE.z*r;const wings=[];for(const side of [-1,1]){const hinge=new THREE.Group();root.add(hinge);const wing=new THREE.Mesh(new THREE.CircleGeometry(.13,12),new THREE.MeshBasicMaterial({color:[0xffbd46,0xa69aff,0xff8bae][i%3],side:THREE.DoubleSide}));wing.position.x=side*.12;wing.scale.y=.7;hinge.add(wing);wings.push(hinge);}scene.add(root);butterflies.push({root,wings,x,z,phase:range(0,6.28)});}
 function update(time){for(const b of butterflies){const x=b.x+Math.sin(time*.33+b.phase)*1.8,z=b.z+Math.cos(time*.23+b.phase)*1.4;b.root.position.set(x,terrainHeight(x,z)+1.1+Math.sin(time*1.5+b.phase)*.25,z);b.root.rotation.y=time*.3+b.phase;b.wings[0].rotation.y=Math.sin(time*14+b.phase)*.9;b.wings[1].rotation.y=-b.wings[0].rotation.y;}}
 update(0);return{occluders,update,cull(camera){for(const item of detail){const s=item.mesh.boundingSphere;item.mesh.visible=camera.position.distanceTo(s.center)-s.radius<item.range;}}};
}
